Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
rxrpc: Fix key parsing memleak

In rxrpc_preparse_xdr_yfs_rxgk(), the memory attached to token->rxgk can be
leaked in a few error paths after it's allocated.

Fix this by freeing it in the "reject_token:" case.

Fixes: 0ca100ff4df6 ("rxrpc: Add YFS RxGK (GSSAPI) security class")
Closes: https://sashiko.dev/#/patchset/20260319150150.4189381-1-dhowells%40redhat.com
Signed-off-by: David Howells <dhowells@redhat.com>
cc: Marc Dionne <marc.dionne@auristor.com>
cc: Jeffrey Altman <jaltman@auristor.com>
cc: Simon Horman <horms@kernel.org>
cc: linux-afs@lists.infradead.org
cc: stable@kernel.org
Link: https://patch.msgid.link/20260408121252.2249051-3-dhowells@redhat.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
` label which only frees `token` but not `token->rxgk`, causing a memory leak. The fix adds `kfree(token->rxgk)` before freeing `token` to properly release the allocated memory.

Here is the patch:
  */
 static int rxrpc_preparse_xdr_yfs_rxgk(struct key_preparsed_payload *prep,
 				       size_t datalen,
 				       const __be32 *xdr, unsigned int toklen)
 {
 	struct rxrpc_key_token *token, **pptoken;
 	time64_t expiry;
 	size_t plen;
 	const __be32 *ticket, *key;
 	s64 tmp;
 	u32 tktlen, keylen;

 	_enter(",{%x,%x,%x,%x},%x",
 	       ntohl(xdr[0]), ntohl(xdr[1]), ntohl(xdr[2]), ntohl(xdr[3]),
 	       toklen);

 	if (6 * 2 + 2 > toklen / 4)
 		goto reject;

 	key = xdr + (6 * 2 + 1);
 	keylen = ntohl(key[-1]);
 	_debug("keylen: %x", keylen);
 	keylen = round_up(keylen, 4);
 	if ((6 * 2 + 2) * 4 + keylen > toklen)
 		goto reject;

 	ticket = xdr + (6 * 2 + 1 + (keylen / 4) + 1);
 	tktlen = ntohl(ticket[-1]);
 	_debug("tktlen: %x", tktlen);
 	tktlen = round_up(tktlen, 4);
 	if ((6 * 2 + 2) * 4 + keylen + tktlen != toklen) {
 		kleave(" = -EKEYREJECTED [%x!=%x, %x,%x]",
 		       (6 * 2 + 2) * 4 + keylen + tktlen, toklen,
 		       keylen, tktlen);
 		goto reject;
 	}

 	plen = sizeof(*token) + sizeof(*token->rxgk) + tktlen + keylen;
 	prep->quotalen += datalen + plen;

 	plen -= sizeof(*token);
 	token = kzalloc_obj(*token);
 	if (!token)
 		goto nomem;

 	token->rxgk = kzalloc(sizeof(*token->rxgk) + keylen, GFP_KERNEL);
 	if (!token->rxgk)
 		goto nomem_token;

 	token->security_index	= RXRPC_SECURITY_YFS_RXGK;
 	token->rxgk->begintime	= xdr_dec64(xdr + 0 * 2);
 	token->rxgk->endtime	= xdr_dec64(xdr + 1 * 2);
 	token->rxgk->level	= tmp = xdr_dec64(xdr + 2 * 2);
 	if (tmp < -1LL || tmp > RXRPC_SECURITY_ENCRYPT)
 		goto reject_token;
 	token->rxgk->lifetime	= xdr_dec64(xdr + 3 * 2);
 	token->rxgk->bytelife	= xdr_dec64(xdr + 4 * 2);
 	token->rxgk->enctype	= tmp = xdr_dec64(xdr + 5 * 2);
 	if (tmp < 0 || tmp > UINT_MAX)
 		goto reject_token;
 	token->rxgk->key.len	= ntohl(key[-1]);
 	token->rxgk->key.data	= token->rxgk->_key;
 	token->rxgk->ticket.len = ntohl(ticket[-1]);

 	if (token->rxgk->endtime != 0) {
 		expiry = rxrpc_s64_to_time64(token->rxgk->endtime);
 		if (expiry < 0)
 			goto expired;
 		if (expiry < prep->expiry)
 			prep->expiry = expiry;
 	}

 	memcpy(token->rxgk->key.data, key, token->rxgk->key.len);

 	/* Pad the ticket so that we can use it directly in XDR */
 	token->rxgk->ticket.data = kzalloc(round_up(token->rxgk->ticket.len, 4),
 					   GFP_KERNEL);
 	if (!token->rxgk->ticket.data)
 		goto nomem_yrxgk;
 	memcpy(token->rxgk->ticket.data, ticket, token->rxgk->ticket.len);

 	_debug("SCIX: %u",	token->security_index);
 	_debug("EXPY: %llx",	token->rxgk->endtime);
 	_debug("LIFE: %llx",	token->rxgk->lifetime);
 	_debug("BYTE: %llx",	token->rxgk->bytelife);
 	_debug("ENC : %u",	token->rxgk->enctype);
 	_debug("LEVL: %u",	token->rxgk->level);
 	_debug("KLEN: %u",	token->rxgk->key.len);
 	_debug("TLEN: %u",	token->rxgk->ticket.len);
 	_debug("KEY0: %*phN",	token->rxgk->key.len, token->rxgk->key.data);
 	_debug("TICK: %*phN",
 	       min_t(u32, token->rxgk->ticket.len, 32), token->rxgk->ticket.data);

 	/* count the number of tokens attached */
 	prep->payload.data[1] = (void *)((unsigned long)prep->payload.data[1] + 1);

 	/* attach the data */
 	for (pptoken = (struct rxrpc_key_token **)&prep->payload.data[0];
 	     *pptoken;
 	     pptoken = &(*pptoken)->next)
 		continue;
 	*pptoken = token;

 	_leave(" = 0");
 	return 0;

 nomem_yrxgk:
 	kfree(token->rxgk);
 nomem_token:
 	kfree(token);
 nomem:
 	return -ENOMEM;
 reject_token:
+	kfree(token->rxgk);
 	kfree(token);
 reject:
 	return -EKEYREJECTED;
 expired:
 	kfree(token->rxgk);
 	kfree(token);
 	return -EKEYEXPIRED;
 }



